const json = $input.first().json;

const raw =
  json.choices?.[0]?.message?.content ??
  json.candidates?.[0]?.content?.parts?.[0]?.text ??
  json.content ??
  json.text;

if (!raw) {
  throw new Error(
    "Réponse LLM introuvable. Structure reçue : " +
      JSON.stringify(Object.keys(json))
  );
}

const cleaned = raw.replace(/```json|```/g, "").trim();
const parsed = JSON.parse(cleaned);

const webhookData = $("Webhook").first().json;

let fileName = "";
let fileId = "";

try {
  const loopItem = $("Loop Over Items (CVs)").item.json;
  fileName = loopItem.name ?? "";
  fileId = loopItem.id ?? "";
} catch (e) {
  fileId = webhookData.body.singleResumeFileId ?? "";
  fileName = webhookData.body.singleResumeFileName ?? fileId;
}

const jobPostCriteria = webhookData.body.jobPostCriteria ?? {};
const globalCriteria = webhookData.body.globalCriteria ?? [];
const minScore = Number(webhookData.body.minScore ?? 10);

const mergedCriteria = {
  intitulePoste: jobPostCriteria.intitulePoste ?? "Non spécifié",

  competencesTechniquesRequises: [
    ...new Set([
      ...(jobPostCriteria.competencesTechniquesRequises ?? []),
      ...globalCriteria
        .filter(gc => gc.category === "technique")
        .map(gc => gc.label),
    ]),
  ],

  competencesGeneralesRequises: [
    ...new Set([
      ...(jobPostCriteria.competencesGeneralesRequises ?? []),
      ...globalCriteria
        .filter(gc => gc.category === "soft-skills")
        .map(gc => gc.label),
    ]),
  ],

  experienceMinimaleAnnees:
    jobPostCriteria.experienceMinimaleAnnees ?? 0,

  formationRequise:
    jobPostCriteria.formationRequise ?? "",

  languesRequises: [
    ...new Set([
      ...(jobPostCriteria.languesRequises ?? []),
      ...globalCriteria
        .filter(gc => gc.category === "langue")
        .map(gc => gc.label),
    ]),
  ],

  certificationsRequises:
    jobPostCriteria.certificationsRequises ?? [],

  missionsPrincipales:
    jobPostCriteria.missionsPrincipales ?? [],
};

return [
  {
    json: {
      cvData: parsed,
      fileName,
      fileId,
      mergedCriteria,
      minScore,

      // DEBUG
      debug: {
        jobPostCriteria,
        globalCriteria,
        mergedCriteria,
        webhookBody: webhookData.body,
      },
    },
  },
];

const inputItem      = $input.first().json;
const cvData         = inputItem.cvData         ?? {};
const mergedCriteria = inputItem.mergedCriteria ?? {};
const fileId         = inputItem.fileId         ?? '';
const fileName       = inputItem.fileName       ?? '';
const intitulePoste  = mergedCriteria.intitulePoste ?? '';

if (!cvData.nom && !cvData.competences) {
  throw new Error("cvData vide ! Structure reçue : " + JSON.stringify(Object.keys(inputItem)));
}

// ── NORMALISATION (nouveau) ─────────────────────────────────────────────────
// Neutralise les variantes d'écriture : "CI/CD" vs "CI-CD" vs "cicd" vs "ci cd"
const normalize = s => (s ?? '').toString().toLowerCase().replace(/[\/\-_\s.]/g, '');

// ── LANGUES ──────────────────────────────────────────────────────────────────
const languesRequises = mergedCriteria.languesRequises ?? [];
const languesCV = (cvData.langues ?? []).map(l => l.toLowerCase());

let scoreLangues, detailLangues;
if (!languesRequises.length) {
  scoreLangues = 100; detailLangues = "Aucune langue spécifiquement requise.";
} else {
  const requises = languesRequises.map(l => l.toLowerCase());
  const matchees = requises.filter(lr =>
    languesCV.some(lc => lc.includes(lr.split(' ')[0]) || lr.includes(lc.split(' ')[0]))
  );
  const ratio = matchees.length / requises.length;
  if (ratio >= 1)        { scoreLangues = 90; detailLangues = "Toutes les langues requises présentes."; }
  else if (ratio >= 0.5) { scoreLangues = 50; detailLangues = `${matchees.length}/${requises.length} langues requises présentes.`; }
  else                   { scoreLangues = 10; detailLangues = "Aucune langue requise présente dans le CV."; }
}

// ── FORMATION ────────────────────────────────────────────────────────────────
const niveau  = (cvData.niveauFormation  ?? '').toLowerCase();
const domaine = (cvData.domaineFormation ?? '').toLowerCase();

const formationMatrix = {
  'bac+5':          { informatique: 92, gestion_informatique: 77, autre: 40 },
  'bac+5_en_cours': { informatique: 72, gestion_informatique: 62, autre: 35 },
  'bac+3':          { informatique: 55, gestion_informatique: 55, autre: 30 },
  'bac+2':          { informatique: 20, gestion_informatique: 20, autre: 10 },
  'bac':            { informatique: 10, gestion_informatique: 10, autre:  5 },
};
const scoreFormation = formationMatrix[niveau]?.[domaine]
  ?? formationMatrix[niveau]?.['autre']
  ?? 5;
const detailFormation = `Niveau: ${niveau || 'inconnu'}, Domaine: ${domaine || 'inconnu'}.`;

// ── EXPÉRIENCE ───────────────────────────────────────────────────────────────
const expCV  = Number(cvData.experiencesAnnees ?? 0);
const expMin = Number(mergedCriteria.experienceMinimaleAnnees ?? 0);
const ecart  = expMin - expCV;

let scoreExp, detailExp;
if (expCV >= expMin)  { scoreExp = 90; detailExp = `${expCV} ans >= minimum requis (${expMin} ans).`; }
else if (ecart <= 2)  { scoreExp = 70; detailExp = `Écart de ${ecart} an(s) avec le minimum requis.`; }
else if (ecart <= 5)  { scoreExp = 42; detailExp = `Écart de ${ecart} ans avec le minimum requis.`; }
else                  { scoreExp = 15; detailExp = `Écart important : ${expCV} ans vs ${expMin} ans requis.`; }

// ── SOFT SKILLS ──────────────────────────────────────────────────────────────
const softSkills = cvData.softSkills ?? [];
const nbSoft = softSkills.length;

let scoreSoft, detailSoft;
if (nbSoft >= 5)      { scoreSoft = 85; detailSoft = `${nbSoft} soft skills : ${softSkills.join(', ')}.`; }
else if (nbSoft >= 3) { scoreSoft = 65; detailSoft = `${nbSoft} soft skills : ${softSkills.join(', ')}.`; }
else if (nbSoft >= 1) { scoreSoft = 42; detailSoft = `${nbSoft} soft skill(s) : ${softSkills.join(', ')}.`; }
else                  { scoreSoft = 10; detailSoft = "Aucun soft skill mentionné."; }

// ── CERTIFICATIONS ───────────────────────────────────────────────────────────
const certificationsRequises = mergedCriteria.certificationsRequises ?? [];
const certificationsCV = (cvData.certifications ?? []).map(c => c.toLowerCase());

let scoreCertif = null, detailCertif = '', hasCertifCritere = false;
let matchedCertif = [], missingCertif = [];

if (certificationsRequises.length > 0) {
  hasCertifCritere = true;
  const requises = certificationsRequises.map(c => c.toLowerCase());
  const matched = [], missing = [];

  requises.forEach(cr => {
    const found = certificationsCV.find(cc =>
      cc.includes(cr.split(' ')[0]) || cr.includes(cc.split(' ')[0])
    );
    if (found) {
      const original = (cvData.certifications ?? []).find(cc =>
        cc.toLowerCase().includes(cr.split(' ')[0]) || cr.includes(cc.toLowerCase().split(' ')[0])
      );
      matched.push(original ?? found);
    } else {
      missing.push(certificationsRequises.find(r => r.toLowerCase() === cr) ?? cr);
    }
  });

  const ratio = matched.length / requises.length;
  if (ratio >= 1)        { scoreCertif = 95; detailCertif = "Toutes les certifications requises présentes."; }
  else if (ratio >= 0.5) { scoreCertif = 60; detailCertif = `${matched.length}/${requises.length} certifications requises présentes.`; }
  else if (ratio > 0)    { scoreCertif = 30; detailCertif = `${matched.length}/${requises.length} certification(s) requise(s) présente(s).`; }
  else                   { scoreCertif = 0;  detailCertif = "Aucune certification requise présente dans le CV."; }

  matchedCertif = matched;
  missingCertif = missing;
}

// ── COMPÉTENCES TECHNIQUES (avec normalisation) ─────────────────────────────
const competencesCV       = cvData.competences ?? [];
const competencesRequises = mergedCriteria.competencesTechniquesRequises ?? [];

const competencesNorm = competencesCV.map(normalize);
const matchesTech = competencesRequises.filter(req =>
  competencesNorm.some(c => c.includes(normalize(req)) || normalize(req).includes(c))
);
const ratioFallback = competencesRequises.length ? matchesTech.length / competencesRequises.length : 1;
let scoreTechFallback;
if (ratioFallback >= 0.7)      scoreTechFallback = 85;
else if (ratioFallback >= 0.4) scoreTechFallback = 60;
else if (ratioFallback > 0)    scoreTechFallback = 30;
else                           scoreTechFallback = 8;

// ── MATCHING DÉTAILLÉ (avec normalisation) ──────────────────────────────────
const competencesGeneralesRequises = mergedCriteria.competencesGeneralesRequises ?? [];
const competencesGeneralesCV = [
  ...(cvData.competences ?? []),
  ...(cvData.competencesGenerales ?? []),
  ...(cvData.softSkills ?? []),
].map(normalize);

const matchedTechInCv    = competencesRequises.filter(req => competencesNorm.some(c => c.includes(normalize(req)) || normalize(req).includes(c)));
const missingTechInCv    = competencesRequises.filter(req => !competencesNorm.some(c => c.includes(normalize(req)) || normalize(req).includes(c)));
const matchedGeneralInCv = competencesGeneralesRequises.filter(req => competencesGeneralesCV.some(c => c.includes(normalize(req)) || normalize(req).includes(c)));
const missingGeneralInCv = competencesGeneralesRequises.filter(req => !competencesGeneralesCV.some(c => c.includes(normalize(req)) || normalize(req).includes(c)));
const matchedLanguesInCv = languesRequises.filter(lr => languesCV.some(lc => lc.includes(lr.toLowerCase().split(' ')[0]) || lr.toLowerCase().includes(lc.split(' ')[0])));
const missingLanguesInCv = languesRequises.filter(lr => !languesCV.some(lc => lc.includes(lr.toLowerCase().split(' ')[0]) || lr.toLowerCase().includes(lc.split(' ')[0])));

// ── PROMPT LLM ───────────────────────────────────────────────────────────────
const body = JSON.stringify({
  model: "openai/gpt-4o-mini",
  messages: [
    {
      role: "system",
      content: "Tu es un expert technique RH. Quand tu évalues les compétences, tu tiens compte des SYNONYMES et ÉQUIVALENCES sémantiques. Ne jamais signaler comme point faible une compétence que le candidat possède sous une autre dénomination."
    },
    {
      role: "user",
      content: `Expert technique RH. Évalue UNIQUEMENT les compétences techniques.
Retourne UNIQUEMENT ce JSON valide sans texte avant ou après :
{
  "score": 0,
  "detail": "max 2 lignes",
  "pointsForts": ["..."],
  "pointsFaibles": ["..."],
  "resumeCandidat": "résumé global candidat max 2 lignes",
  "matchedTech": ["compétences requises TROUVÉES"],
  "missingTech": ["compétences requises MANQUANTES"]
}

Règles score :
- >= 70% compétences requises présentes → score 75-95
- 40-70% → score 45-74
- < 40% → score 10-44
- Aucune → score 0-15

Compétences CV : ${JSON.stringify(competencesCV)}
Compétences requises : ${JSON.stringify(competencesRequises)}`
    }
  ]
});

return [{
  json: {
    body, scoreTechFallback,
    scoreLangues, detailLangues,
    scoreFormation, detailFormation,
    scoreExp, detailExp,
    scoreSoft, detailSoft,
    hasCertifCritere, scoreCertif, detailCertif,
    matchedCertif, missingCertif,
    fileId, fileName, intitulePoste,
    cvData, mergedCriteria,
    matchedTechInCv, missingTechInCv,
    matchedGeneralInCv, missingGeneralInCv,
    matchedLanguesInCv, missingLanguesInCv,
  }
}];

const meta    = $('Code JS (prépare scoring)').item.json;
const llmJson = $input.first().json;

const raw = llmJson.choices?.[0]?.message?.content ?? llmJson.content ?? llmJson.text;

let techResult;
try {
  techResult = JSON.parse((raw ?? '').replace(/```json|```/g, '').trim());
} catch(e) {
  techResult = {
    score: meta.scoreTechFallback,
    detail: "Score calculé automatiquement.",
    pointsForts: [],
    pointsFaibles: [],
    resumeCandidat: meta.cvData?.resume ?? '',
    matchedTech: meta.matchedTechInCv ?? [],
    missingTech: meta.missingTechInCv ?? [],
  };
}

const scoreTech = Number(techResult.score ?? meta.scoreTechFallback);
const hasCertif   = meta.hasCertifCritere ?? false;
const scoreCertif = meta.scoreCertif ?? null;

let scoreGlobal;
if (hasCertif && scoreCertif !== null) {
  scoreGlobal = Math.round(
    scoreTech           * 0.35 +
    meta.scoreExp       * 0.25 +
    meta.scoreFormation * 0.13 +
    meta.scoreSoft      * 0.09 +
    meta.scoreLangues   * 0.05 +
    scoreCertif         * 0.13
  );
} else {
  scoreGlobal = Math.round(
    scoreTech           * 0.40 +
    meta.scoreExp       * 0.30 +
    meta.scoreFormation * 0.15 +
    meta.scoreSoft      * 0.10 +
    meta.scoreLangues   * 0.05
  );
}

const minScore = Number($('Webhook').first().json.body.minScore ?? 10);

// ✅ SOURCE DE VÉRITÉ = calcul JS déterministe (meta.*)
// Le LLM (techResult.matchedTech/missingTech) n'est PAS utilisé ici pour le
// résultat officiel, il est conservé à part dans "llmSuggested" (debug/référence)
const matchedCriteriaInCv = {
  competencesTechniques: {
    matched: meta.matchedTechInCv ?? [],
    missing: meta.missingTechInCv ?? [],
  },
  competencesGenerales: {
    matched: meta.matchedGeneralInCv ?? [],
    missing: meta.missingGeneralInCv ?? [],
  },
  langues: {
    matched: meta.matchedLanguesInCv ?? [],
    missing: meta.missingLanguesInCv ?? [],
  },
  ...(hasCertif ? {
    certifications: {
      matched: meta.matchedCertif ?? [],
      missing: meta.missingCertif ?? [],
    }
  } : {}),
};

const termsToHighlight = [
  ...(matchedCriteriaInCv.competencesTechniques?.matched ?? []),
  ...(matchedCriteriaInCv.competencesGenerales?.matched ?? []),
  ...(matchedCriteriaInCv.langues?.matched ?? []),
  ...(matchedCriteriaInCv.certifications?.matched ?? []),
  ...(meta.cvData?.softSkills ?? []),
  ...(meta.cvData?.experiences ?? []).map(e => e.poste).filter(Boolean),
  ...(meta.cvData?.experiences ?? []).map(e => e.entreprise).filter(Boolean),
  ...(meta.cvData?.formations ?? []).map(f => f.diplome).filter(Boolean),
  ...(meta.cvData?.formations ?? []).map(f => f.ecole).filter(Boolean),
].filter(t => t && t.length > 1);

return [{
  json: {
    fileId:   meta.fileId,
    fileName: meta.fileName,
    jobTitle: meta.intitulePoste,
    scoreGlobal,
    status: scoreGlobal >= minScore ? 'MATCH' : 'NO_MATCH',
    termsToHighlight,
    matchedCriteriaInCv,
    // 🆕 Référence qualitative du LLM, gardée à part pour debug/comparaison
    // (ne remplace jamais matchedCriteriaInCv)
    llmSuggested: {
      matchedTech: techResult.matchedTech ?? [],
      missingTech: techResult.missingTech ?? [],
    },
    detail: {
      scoreGlobal,
      technicalSkills: { score: scoreTech,          detail: techResult.detail ?? '' },
      experience:      { score: meta.scoreExp,       detail: meta.detailExp },
      education:       { score: meta.scoreFormation, detail: meta.detailFormation },
      softSkills:      { score: meta.scoreSoft,      detail: meta.detailSoft },
      languages:       { score: meta.scoreLangues,   detail: meta.detailLangues },
      ...(hasCertif ? {
        certifications: {
          score: scoreCertif,
          detail: meta.detailCertif,
          matched: meta.matchedCertif ?? [],
          missing: meta.missingCertif ?? [],
        }
      } : {}),
      strengths:      techResult.pointsForts   ?? [],
      weaknesses:     techResult.pointsFaibles ?? [],
      resume:         techResult.resumeCandidat ?? meta.cvData?.resume ?? '',
      recommendation: scoreGlobal >= minScore ? 'retenir' : 'ecarter',
    },
    createdAt: new Date().toISOString()
  }
}];

const webhookData = $('Webhook').first().json;
const inputItem = $input.first();

return [{
  json: {
    id: webhookData.body.singleResumeFileId,
    name: webhookData.body.singleResumeFileName ?? webhookData.body.singleResumeFileId,
  },
  binary: inputItem.binary
}];

// APRÈS (corrigé) :
const item = $input.first();

// La réponse est déjà binaire (responseFormat: file)
// On récupère le nom depuis les métadonnées ou on met un nom par défaut
const originalFileName = item.binary?.data?.fileName
  ?? item.json?.fileName
  ?? 'converted.pdf';

const baseName = originalFileName.replace(/\.docx$/i, '');

return [{
  json: {},
  binary: {
    data: {
      ...item.binary.data,
      mimeType: 'application/pdf',
      fileExtension: 'pdf',
      fileName: `${baseName}.pdf`
    }
  }
}];

const item = $input.first();

// Récupérer le buffer binaire
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');

// Convertir en base64
const base64String = binaryBuffer.toString('base64');

return [{
  json: {
    fileName: item.binary.data.fileName,
    mimeType: item.binary.data.mimeType,
    fileBase64: base64String
  },
  binary: item.binary
}];
